sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float density;
uniform float speckSize;
uniform float saltRatio;
layout(color) uniform half4 saltColor;
layout(color) uniform half4 pepperColor;
uniform float animated;
uniform float rate;
uniform float strength;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float t = animated > 0.5 ? floor(time * rate) : 0.0;
    float2 p = floor(coord / max(speckSize, 1.0)) + t * 13.1;
    float hit = step(1.0 - density, hash21(p));
    float isSalt = step(1.0 - saltRatio, hash21(p + 5.3));
    float3 sp = mix(float3(pepperColor.rgb), float3(saltColor.rgb), isSalt);
    float3 o = mix(s, sp, hit * strength);
    return fin(c, float4(o * c.a, c.a), 1.0);
}
